#!/usr/bin/env node
// Regenerate contracts derived from Rust:
//   - engine types (ts-rs)    -> packages/web-engine/src/generated/*.ts
//   - OpenAPI spec (utoipa)   -> schemas/generated/openapi.json
//   - TS API types            -> packages/api-client/src/generated/schema.ts
// Generated files are committed; CI re-runs this and fails on drift.
import { mkdirSync, readdirSync, rmSync, writeFileSync } from "node:fs";
import { execFileSync } from "node:child_process";
import { join } from "node:path";
import { root, run } from "./lib.mjs";

const tsDir = join(root, "packages", "web-engine", "src", "generated");
rmSync(tsDir, { recursive: true, force: true });
mkdirSync(tsDir, { recursive: true });
await run("cargo", ["test", "-q", "-p", "karbird-engine-core", "--features", "ts", "--lib", "export_bindings"], {
  env: { ...process.env, TS_RS_EXPORT_DIR: tsDir },
});
const names = readdirSync(tsDir)
  .filter((f) => f.endsWith(".ts") && f !== "index.ts")
  .map((f) => f.slice(0, -3))
  .sort();
writeFileSync(
  join(tsDir, "index.ts"),
  `// Generated by scripts/codegen.mjs. Do not edit.\n${names.map((n) => `export type { ${n} } from "./${n}";`).join("\n")}\n`,
);

const schemaDir = join(root, "schemas", "generated");
mkdirSync(schemaDir, { recursive: true });
const spec = execFileSync("cargo", ["run", "-q", "-p", "karbird-api", "--", "openapi"], {
  cwd: root,
  encoding: "utf8",
  maxBuffer: 64 * 1024 * 1024,
});
const specPath = join(schemaDir, "openapi.json");
writeFileSync(specPath, JSON.stringify(JSON.parse(spec), null, 2) + "\n");

const clientDir = join(root, "packages", "api-client", "src", "generated");
mkdirSync(clientDir, { recursive: true });
await run("pnpm", ["--filter", "@karbird/api-client", "exec", "openapi-typescript", specPath, "-o", join(clientDir, "schema.ts")]);
console.error("[codegen] done");
